import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { report } from '@onebudgetspec/sdk';
import { sourceDigest } from './workflow-graph.mjs';
const args = process.argv.slice(2);
if (args.length !== 4 || args[0] !== '--metric' || !['jobs-per-run', 'runs-per-change'].includes(args[1]) || args[2] !== '--telemetry') throw new Error('usage: macos-budget.mjs --metric jobs-per-run|runs-per-change --telemetry <JSON path>');
const telemetry = JSON.parse(readFileSync(resolve(args[3]), 'utf8'));
if (telemetry.schemaVersion !== 1 || telemetry.sourceDigest !== sourceDigest()) throw new Error('missing or stale Mac policy telemetry; run github-workflows:test');
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const strings = value => Array.isArray(value) && value.every(v => typeof v === 'string');
const rowValid = row => object(row) && ['workflow', 'job', 'runner', 'event', 'displayName', 'head'].every(k => typeof row[k] === 'string') && typeof row.macos === 'boolean' && typeof row.enabled === 'boolean' && object(row.matrix) && strings(row.targets) && strings(row.needs) && (row.tag === null || typeof row.tag === 'string');
const runValid = run => object(run) && typeof run.workflow === 'string' && Array.isArray(run.rows) && run.rows.every(rowValid);
const scenarioValid = s => object(s) && typeof s.id === 'string' && Array.isArray(s.runs) && s.runs.every(runValid);
const lifecycleValid = l => object(l) && typeof l.id === 'string' && strings(l.events) && Array.isArray(l.spendingRuns) && l.spendingRuns.every(r => object(r) && ['workflow', 'event', 'scenario'].every(k => typeof r[k] === 'string') && Array.isArray(r.jobs) && r.jobs.every(rowValid));
if (!strings(telemetry.releaseTargets) || !telemetry.releaseTargets.length || !Array.isArray(telemetry.scenarios) || !telemetry.scenarios.length || !telemetry.scenarios.every(scenarioValid) || !Array.isArray(telemetry.lifecycles) || !telemetry.lifecycles.length || !telemetry.lifecycles.every(lifecycleValid)) throw new Error('invalid nested Mac policy telemetry; rerun github-workflows:test');
for (const metric of ['jobsPerRun', 'runsPerChange']) if (!Number.isSafeInteger(telemetry[metric]) || telemetry[metric] < 0) throw new Error(`invalid telemetry metric ${metric}; rerun github-workflows:test`);
const recordedJobs = Math.max(...telemetry.scenarios.flatMap(s => s.runs.map(r => r.rows.filter(row => row.macos).length)));
const recordedRuns = Math.max(...telemetry.lifecycles.map(l => l.spendingRuns.length));
if (recordedJobs !== telemetry.jobsPerRun || recordedRuns !== telemetry.runsPerChange) throw new Error('inconsistent telemetry totals; rerun github-workflows:test');
const value = args[1] === 'jobs-per-run' ? telemetry.jobsPerRun : telemetry.runsPerChange;
const detail = JSON.stringify({ sourceDigest: telemetry.sourceDigest, releaseTargets: telemetry.releaseTargets, scenarios: telemetry.scenarios.map(s => ({ scenario: s.id, workflows: s.runs.map(r => ({ workflow: r.workflow, jobs: r.rows.filter(row => row.macos) })) })), lifecycles: telemetry.lifecycles });
if (!report(value, detail)) console.log(JSON.stringify({ metric: args[1], value, detail: JSON.parse(detail) }));
